from fractions import Fraction
def value(coeffs, a):
    n = len(coeffs) - 1
    return sum(coeffs[i] * a ** (n - i) for i in range(len(coeffs)))
def solve(p, q, a):
    top = value(p, a)
    bottom = value(q, a)
    print(f"p = {p}, q = {q}, a = {a}")
    print(f"  p({a}) = {top}, q({a}) = {bottom}")
    if bottom != 0:
        print(f"  q({a}) != 0, so the limit is {Fraction(top, bottom)}")
    elif top == 0:
        print("  0/0: substitution doesn't apply, simplify first")
    else:
        print(f"  {top}/0: no finite limit")
def read_poly():
    n = int(input())
    coeffs = []
    for i in range(n):
        coeffs.append(int(input()))
    return coeffs
k = int(input())
for i in range(k):
    p = read_poly()
    q = read_poly()
    a = int(input())
    solve(p, q, a)
